/**
 * Standard pharmacy catalogue for Indian clinic practice (version 2) — about 300 of the most commonly stocked medicines, paediatric first
 * and adult as well, so a fresh install starts with a ready drug list. Every clinic can edit prices, add/remove items and manage stock
 * from Pharmacy → Drug List.
 *
 * How a row is written (so the prescription box and the purchase bill show a real composition, not just a name):
 *   name         what it is called on the pack — a brand ("Dolo 650", "Ascoril LS Syrup") or, for generics, "<generic> <strength> <form>"
 *   generic_name every active ingredient, joined with " + "
 *   strength     the amount of EACH ingredient in one unit, with its own unit: "500 mg + 125 mg" for a tablet; for a liquid the amount per
 *                volume — "250 mg/5 ml", "200 mg + 28.5 mg/5 ml", "100 mg/ml" for drops; "1% + 0.025%" for a cream
 *   pack_size    units in one pack (tablets in a strip, ml in a bottle, doses in an inhaler)
 * A variant is its OWN row ("Augmentin Duo Syrup" 200 + 28.5 and "Augmentin DDS Syrup" 400 + 57 are different medicines).
 *
 * MRPs are indicative (₹, per pack) — every clinic sets its own, and so can it change the GST of any drug. GST here is the current rate
 * for medicines (5 %, since 22 Sep 2025). Schedule: H1 for the third-generation cephalosporins, levofloxacin, tramadol, diazepam,
 * rifampicin and alprazolam; H for other prescription medicines; OTC otherwise.
 *
 * Loading the catalogue only ADDS drugs whose name isn't already present (and corrects the composition of a row nobody has edited — see
 * db/catalogue.ts), so it is safe to run on an existing catalogue. The list that releases up to 0.9.7 shipped is frozen in
 * pharmacy-catalog-v1.ts.
 */
export interface CatalogDrug {
  name: string;               // as stocked / as on the pack
  generic_name: string;
  form: 'Tablet' | 'Capsule' | 'Syrup' | 'Suspension' | 'Injection' | 'Drops' | 'Ointment' | 'Cream' | 'Gel' | 'Inhaler' | 'Respules' | 'Sachet' | 'Solution' | 'Spray';
  strength: string;
  schedule: 'H' | 'H1' | 'G' | 'X' | 'OTC';
  gst_rate: number;           // 5 | 18
  default_mrp: number;        // ₹ per pack
  pack_size?: number;         // units per strip / bottle / inhaler
}

